exercises.solution:
def parse_traceback(text):
    lines = text.strip().splitlines()
    error_type, _, message = lines[-1].partition(": ")
    file = None
    line_no = None
    for line in lines:
        stripped = line.strip()
        if stripped.startswith('File "'):
            file = stripped.split('"')[1]
            line_no = int(stripped.split("line ")[1].split(",")[0])
    return {"type": error_type, "message": message, "file": file, "line": line_no}

def error_category(name):
    if name in ("SyntaxError", "IndentationError"):
        return "cú pháp"
    elif name == "NameError":
        return "tên"
    elif name == "TypeError":
        return "kiểu"
    elif name == "ValueError":
        return "giá trị"
    elif name == "ZeroDivisionError":
        return "toán học"
    elif name in ("IndexError", "KeyError", "AttributeError"):
        return "truy cập"
    elif name == "FileNotFoundError":
        return "file"
    elif name in ("ModuleNotFoundError", "ImportError"):
        return "thư viện"
    return "khác"

