exercises.solution:
def split_path(path):
    folder, _, name = path.rpartition("/")
    return folder, name


def extension(path):
    name = split_path(path)[1]
    if "." in name:
        return "." + name.rsplit(".", 1)[1]
    return ""

def join_path(*parts):
    if not parts:
        return ""
    cleaned = [parts[0].rstrip("/")] + [p.strip("/") for p in parts[1:]]
    return "/".join(p for p in cleaned if p)

