exercises.solution:
def uv_command(action, target=None):
    if action == "repl":
        return "uv run python"
    if action not in ("run", "add", "init"):
        raise ValueError(f"Không biết lệnh: {action}")
    if not target:
        raise ValueError("Thiếu tham số")
    if action == "run":
        return f"uv run python {target}"
    return f"uv {action} {target}"

