def collatz(n):
    if n <= 0:
        return []
    seq = [n]
    while n != 1:
        n = n // 2 if n % 2 == 0 else 3 * n + 1
        seq.append(n)
    return seq

def triangle(n):
    lines = []
    for i in range(1, n + 1):
        lines.append(("*" * i).rjust(n))
    return "\n".join(lines)


