exercises.solution:
def chunk(items, size):
    if size <= 0:
        raise ValueError("size phải > 0")
    result = []
    for i in range(0, len(items), size):
        result.append(items[i:i + size])
    return result

def missing_number(nums):
    n = len(nums) + 1
    return n * (n + 1) // 2 - sum(nums)

def total_and_average(nums):
    if not nums:
        return 0, 0.0
    total = sum(nums)
    return total, round(total / len(nums), 2)

def remove_duplicates(items):
    seen = set()
    result = []
    for x in items:
        if x not in seen:
            seen.add(x)
            result.append(x)
    return result

def index_of_max(nums):
    if not nums:
        return -1
    return nums.index(max(nums))

