exercises.solution:
def top_n(scores, n):
    return sorted(scores, key=lambda name: (-scores[name], name))[:n]


def passed(scores, threshold=5):
    return {name: s for name, s in scores.items() if s >= threshold}

def safe_int(text, default=0):
    try:
        return int(text)
    except (ValueError, TypeError):
        return default

def average_of(nums):
    try:
        return sum(nums) / len(nums)
    except ZeroDivisionError:
        return None

