import json
from pathlib import Path


def _read(path):
    p = Path(path)
    if not p.exists():
        return {}
    return json.loads(p.read_text(encoding="utf-8"))


def save(path, key, value):
    p = Path(path)
    data = _read(p)
    data[key] = value
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8")


def load(path, key, default=None):
    return _read(path).get(key, default)

import csv


def revenue_by_product(path):
    totals = {}
    with open(path, newline="", encoding="utf-8") as f:
        for row in csv.DictReader(f):
            try:
                amount = float(row["qty"]) * float(row["price"])
            except ValueError:
                continue
            totals[row["product"]] = totals.get(row["product"], 0) + amount
    ranked = sorted(totals.items(), key=lambda kv: kv[1], reverse=True)
    return {product: round(total, 2) for product, total in ranked}

