from dataclasses import dataclass


@dataclass
class Item:
    name: str
    price: float
    qty: int = 0

    @property
    def value(self):
        return self.price * self.qty


class Inventory:
    def __init__(self):
        self._items = {}

    def add(self, name, price, qty):
        if name in self._items:
            item = self._items[name]
            item.qty += qty
            item.price = price
        else:
            self._items[name] = Item(name, price, qty)

    def remove(self, name, qty):
        item = self._items.get(name)
        if item is None or item.qty < qty:
            raise ValueError("Không đủ hàng")
        item.qty -= qty
        if item.qty == 0:
            del self._items[name]

    def total_value(self):
        return sum(i.value for i in self._items.values())

    def cheapest(self, n):
        return [i.name for i in sorted(self._items.values(), key=lambda i: i.price)[:n]]

    def __len__(self):
        return len(self._items)

    def __contains__(self, name):
        return name in self._items

