import operator

OPS = {"+": operator.add, "-": operator.sub, "*": operator.mul, "/": operator.truediv}


def to_number(tok):
    try:
        return int(tok)
    except ValueError:
        return float(tok)


def eval_rpn(expr):
    stack = []
    for tok in expr.split():
        if tok in OPS:
            if len(stack) < 2:
                raise ValueError("Thiếu toán hạng")
            b = stack.pop()
            a = stack.pop()
            stack.append(OPS[tok](a, b))
        else:
            stack.append(to_number(tok))
    if len(stack) != 1:
        raise ValueError("Biểu thức không hợp lệ")
    return stack[0]

