def lis(nums):
    if not nums:
        return []
    n = len(nums)
    length = [1] * n
    prev = [-1] * n
    for i in range(n):
        for j in range(i):
            if nums[j] < nums[i] and length[j] + 1 > length[i]:
                length[i] = length[j] + 1
                prev[i] = j
    i = max(range(n), key=length.__getitem__)
    out = []
    while i != -1:
        out.append(nums[i])
        i = prev[i]
    return out[::-1]

