def subsets_with_sum(nums, target):
    nums = sorted(nums)
    result = []

    def backtrack(start, path, total):
        if total == target:
            result.append(path[:])
        for i in range(start, len(nums)):
            if total + nums[i] > target:
                break
            path.append(nums[i])
            backtrack(i + 1, path, total + nums[i])
            path.pop()

    backtrack(0, [], 0)
    return sorted(result)

