    try:
        fetch_json("http://x", get, retries=2)
    except RuntimeError as e:
        assert "500" in str(e) and len(calls) == 3
        return
    assert False


def test_client_error_no_retry():
    """404 không thử lại"""
    get, calls = make_get([404])
    try:
        fetch_json("http://x", get)
    except ValueError as e:
        assert "404" in str(e) and len(calls) == 1
