def fetch_json(url, http_get, retries=2):
    code = None
    for _ in range(retries + 1):
        resp = http_get(url, timeout=10)
        code = resp.status_code
        if 200 <= code < 300:
            return resp.json()
        if 400 <= code < 500:
            raise ValueError(f"Lỗi client {code}")
    raise RuntimeError(f"Server lỗi {code}")

