from collections import Counter


def feedback(guess, answer):
    result = ["_"] * len(guess)
    remaining = Counter()
    for i, (g, a) in enumerate(zip(guess, answer)):
        if g == a:
            result[i] = "G"
        else:
            remaining[a] += 1
    for i, g in enumerate(guess):
        if result[i] != "G" and remaining[g] > 0:
            result[i] = "Y"
            remaining[g] -= 1
    return "".join(result)


def is_valid_guess(word, dictionary):
    return len(word) == 5 and word.isalpha() and word.lower() in dictionary

import json
from dataclasses import asdict, dataclass
from datetime import date
from pathlib import Path


@dataclass
class Expense:
    amount: float
    category: str
    day: str
    note: str = ""


class Tracker:
    def __init__(self, items=None):
        self.items = list(items or [])

    def add(self, amount, category, day, note=""):
        if amount <= 0:
            raise ValueError("Số tiền phải dương")
        date.fromisoformat(day)
        self.items.append(Expense(amount, category.lower(), day, note))

    def total(self, category=None):
        cat = category.lower() if category else None
        return sum(e.amount for e in self.items if cat is None or e.category == cat)

    def by_month(self):
        totals = {}
        for e in self.items:
            totals[e.day[:7]] = totals.get(e.day[:7], 0) + e.amount
        return dict(sorted(totals.items()))

    def top_categories(self, n):
        totals = {}
        for e in self.items:
            totals[e.category] = totals.get(e.category, 0) + e.amount
        return sorted(totals.items(), key=lambda kv: kv[1], reverse=True)[:n]

    def save(self, path):
        p = Path(path)
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(json.dumps([asdict(e) for e in self.items], ensure_ascii=False, indent=2),
                     encoding="utf-8")

    @classmethod
    def load(cls, path):
        p = Path(path)
        if not p.exists():
            return cls()
        return cls(Expense(**d) for d in json.loads(p.read_text(encoding="utf-8")))

