exercises.solution:
import sqlite3


class TodoStore:
    def __init__(self, db_path=":memory:"):
        self.conn = sqlite3.connect(db_path)
        with self.conn:
            self.conn.execute(
                "CREATE TABLE IF NOT EXISTS todo ("
                "id INTEGER PRIMARY KEY AUTOINCREMENT, "
                "title TEXT NOT NULL, "
                "done INTEGER NOT NULL DEFAULT 0)"
            )

    def add(self, title):
        title = title.strip()
        if not title:
            raise ValueError("Tiêu đề rỗng")
        with self.conn:
            cur = self.conn.execute("INSERT INTO todo (title) VALUES (?)", (title,))
        return cur.lastrowid

    def complete(self, todo_id):
        with self.conn:
            cur = self.conn.execute("UPDATE todo SET done = 1 WHERE id = ?", (todo_id,))
        return cur.rowcount == 1

    def pending(self):
        rows = self.conn.execute("SELECT title FROM todo WHERE done = 0 ORDER BY id").fetchall()
        return [r[0] for r in rows]

    def search(self, keyword):
        rows = self.conn.execute("SELECT title FROM todo ORDER BY id").fetchall()
        return [r[0] for r in rows if keyword.lower() in r[0].lower()]

    def stats(self):
        total, done = self.conn.execute(
            "SELECT COUNT(*), COALESCE(SUM(done), 0) FROM todo").fetchone()
        return {"total": total, "done": done, "pending": total - done}

    def close(self):
        self.conn.close()

