def human_time(seconds):
    if seconds < 60:
        return f"{seconds:.1f} giây"
    if seconds < 3600:
        return f"{seconds / 60:.1f} phút"
    if seconds < 86400:
        return f"{seconds / 3600:.1f} giờ"
    if seconds < 86400 * 365:
        return f"{seconds / 86400:.1f} ngày"
    return f"{seconds / (86400 * 365):.1f} năm"

