exercises.solution:
import time


class LoginLimiter:
    def __init__(self, max_fails=5, lock_seconds=300, clock=time.monotonic):
        self.max_fails = max_fails
        self.lock_seconds = lock_seconds
        self.clock = clock
        self.fails = {}
        self.locked_until = {}

    def allowed(self, user):
        return self.clock() >= self.locked_until.get(user, 0)

    def retry_after(self, user):
        return max(0, self.locked_until.get(user, 0) - self.clock())

    def record(self, user, success):
        if success:
            if self.allowed(user):
                self.fails.pop(user, None)
            return
        self.fails[user] = self.fails.get(user, 0) + 1
        if self.fails[user] >= self.max_fails:
            self.locked_until[user] = self.clock() + self.lock_seconds
            self.fails.pop(user)

import hashlib
import hmac
import os


def hash_password(password, salt=None, iterations=100_000):
    salt = salt or os.urandom(16)
    digest = hashlib.pbkdf2_hmac("sha256", password.encode(), salt, iterations)
    return f"pbkdf2_sha256${iterations}${salt.hex()}${digest.hex()}"


def verify_password(password, stored):
    try:
        algo, iters, salt_hex, hash_hex = stored.split("$")
        if algo != "pbkdf2_sha256":
            return False
        digest = hashlib.pbkdf2_hmac("sha256", password.encode(), bytes.fromhex(salt_hex), int(iters))
    except (ValueError, TypeError, AttributeError):
        return False
    return hmac.compare_digest(digest.hex(), hash_hex)

def detect_bruteforce(events, max_fails=5, window=60):
    fails = {}
    for t, ip, ok in events:
        if not ok:
            fails.setdefault(ip, []).append(t)
    flagged = set()
    for ip, times in fails.items():
        times.sort()
        left = 0
        for right in range(len(times)):
            while times[right] - times[left] > window:
                left += 1
            if right - left + 1 >= max_fails:
                flagged.add(ip)
                break
    return sorted(flagged)
